intro:
Returns an element at specified relative location.

Let parent_ and inner_ be the data members of the iterator. Equivalent to:

return apply([&](const auto&... iters) -> decltype(auto)
             {
                return invoke(*parent_->fun_, iters[n]...);
             },
             inner_.current_);

examples.code:
#include <ranges>
#include <iterator>
#include <functional>
#include <utility>
#include <cassert>
#include <iostream>

int main() {
    int values[]{3, 5, 7, 9};
    [[maybe_unused]] int nested[][2]{{1, 2}, {3, 4}};
    [[maybe_unused]] std::pair<int, int> pairs[]{{1, 10}, {2, 20}, {3, 30}};
    auto view =
        std::views::adjacent_transform<2>(values, [](int a, int b) { return a + b; });
    auto position = view.begin();
    auto finish = view.end();
    assert(position != finish);
    (void)*position;
    auto copy = position;
    assert(copy == position);
    ++position;
    assert(position != copy);
    --position;
    assert(position == copy);
    position += 1;
    position -= 1;
    assert(position - copy == 0);
    assert(copy + 1 > copy);
    assert(1 + copy == copy + 1);
    (void)position[0];
    (void)std::ranges::iter_move(copy);

    assert(std::ranges::distance(view) > 0);
    std::cout << "Checks passed\n";
}
